INSERT into mall_order (
    id, order_no, store_id, user_id, openid, contact, address, remark,
    goods_amount, delivery_fee, pay_amount, pay_amount_fen, pay_status,
    prepay_id, created_by, created_time, deleted
) value (
    #{id}, #{orderNo}, #{storeId}, #{userId}, #{openid}, #{contact}, #{address}, #{remark},
    #{goodsAmount}, #{deliveryFee}, #{payAmount}, #{payAmountFen}, #{payStatus},
    #{prepayId}, #{createdBy}, #{createdTime}, #{deleted}
)

