select * from mall_order

    deleted = 0

        and user_id = #{userId}


        and store_id = #{storeId}


        and pay_status in

            #{status}



        and pay_status = #{payStatus}


        and order_no = #{orderNo}


order by created_time desc, id desc

mapper.update:
update mall_order
set pay_status = 2,
    update_time = #{closedTime}
where order_no = #{orderNo}
  and pay_status = 0
  and deleted = 0

mapper.select:
select * from mall_order
where deleted = 0
  and pay_status = 0
  and created_time < #{expireBefore}
order by created_time asc, id asc
limit #{limit}

select id, type, title, orderNo, amount, time, status from ( select concat(order_no, '-in') as id, 'income' as type, '订单收入' as title, order_no as orderNo, pay_amount as amount, date_format(paid_time, '%Y-%m-%d %H:%i:%s') as time, '已到账' as status from mall_order where deleted = 0 and store_id = #{storeId} and paid_time is not null and pay_status in (1, 3, 4, 5)
and paid_time >= #{startTime}
and paid_time < #{endTime}
union all select concat(order_no, '-out') as id, 'expense' as type, '订单退款' as title, order_no as orderNo, refund_amount as amount, date_format(ifnull(refund_time, update_time), '%Y-%m-%d %H:%i:%s') as time, case when pay_status = 5 then '已全额退款' when pay_status = 4 then '部分退款' else '已退款' end as status from mall_order where deleted = 0 and store_id = #{storeId} and ifnull(refund_amount, 0) > 0
and ifnull(refund_time, update_time) >= #{startTime}
and ifnull(refund_time, update_time) < #{endTime}
) t
and t.type = #{type}
order by t.time desc, t.orderNo desc

select
    ifnull((
        select sum(pay_amount)
        from mall_order
        where deleted = 0
          and store_id = #{storeId}
          and paid_time is not null
          and pay_status in (1, 3, 4, 5)

              and paid_time >= #{startTime}


              and paid_time < #{endTime}

    ), 0) as income,
    ifnull((
        select sum(refund_amount)
        from mall_order
        where deleted = 0
          and store_id = #{storeId}
          and ifnull(refund_amount, 0) > 0

              and ifnull(refund_time, update_time) >= #{startTime}


              and ifnull(refund_time, update_time) < #{endTime}

    ), 0) as expense
